# -*- coding: utf-8 -*-
# one-time patch v43: 12 more abbreviations in the abbreviations tab, sw.js cache bump
import hashlib, json
b = open("index.html", "rb").read()
assert hashlib.sha256(b).hexdigest() == "5d64b599f354c8add6769a102962c603ecfa256f64e440c34a73bd5de19877c4", "index.html is not the expected version"
h = b.decode("utf-8")
pairs = json.loads("[[\",{\\\"a\\\":\\\"אגל״א\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"אגו״ח\\\",\\\"e\\\":\\\"אגודת חסידי חב״ד\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"אגל״א\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"אחה״פ\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"אחב״י\\\",\\\"e\\\":\\\"אחינו בני ישראל\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"אחה״ע\\\",\\\"e\\\":\\\"אותיות הגרון (א, ח, ה, ע)\\\",\\\"m\\\":\\\"ראשי התיבות אחה״ע מייצגים את אותיות הגרון, אחד מחמשת מוצאות הפה בדקדוק העברי ובקבלה.\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"אחה״פ\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"הגש״פ\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"הגר״א\\\",\\\"e\\\":\\\"הגאון (רבי אליהו) מווילנא\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"הגש״פ\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"זעג״ז\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"ז״ע\\\",\\\"e\\\":\\\"זעיר אנפין\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"זעג״ז\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"י״ל\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"יי״ש\\\",\\\"e\\\":\\\"יין שרף\\\",\\\"m\\\":\\\"אלכוהול.\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"י״ל\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"עיוה״כ\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"עיה״ק\\\",\\\"e\\\":\\\"עיר הקודש\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"עיוה״כ\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"רו״ס\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"רו״כ\\\",\\\"e\\\":\\\"רובל כסף\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"רו״ס\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"רמ״מ\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"רמ״ל\\\",\\\"e\\\":\\\"רבי משה ליב מסאסוב\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"רמ״מ\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"רפ״י\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"רפו״ש\\\",\\\"e\\\":\\\"רפואה שלמה\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"רפ״י\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"רש״י\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"רשב״ץ\\\",\\\"e\\\":\\\"ר׳ שמואל בצלאל שפטיל\\\",\\\"m\\\":\\\"מחשובי חסידי הצמח צדק.\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"רש״י\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"תו״ח\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"תוה״ק\\\",\\\"e\\\":\\\"תורתנו הקדושה\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"\\\"},{\\\"a\\\":\\\"תו״ח\\\",\\\"e\\\":\"], [\"עם הפיענוח שלהם (2,334).\", \"עם הפיענוח שלהם (2,346).\"]]")
for a, r in pairs:
    assert h.count(a) == 1, a
    h = h.replace(a, r)
out = h.encode("utf-8")
assert hashlib.sha256(out).hexdigest() == "8e13a55665181ff51eb007f887f5504eb78dc7a6d81ecd2f75d7cec7b35abe5a", "patched index.html hash mismatch"
open("index.html", "wb").write(out)
sw = open("sw.js", encoding="utf-8").read()
old = 'const VERSION = "bar-hasaga-v42-abbr-round2";'
assert sw.count(old) == 1
open("sw.js", "w", encoding="utf-8").write(sw.replace(old, 'const VERSION = "bar-hasaga-v43-abbr-round2b";'))
print("ok")
